const chip=(t,id)=>{const x=E.team(t,id);return `<span class="team-chip"><i class="color-dot" style="--color:${safeColor(x?.color)}"></i>${esc(x?.name)}</span>`};
const safeColor=c=>/^#[0-9a-f]{6}$/i.test(c??'')?c:'#315ae8';
function initialData(){return {schema:1,updatedAt:0,revision:0,events:[],activeId:null}}
function load(){for(const key of[KEY,BACKUP])try{const v=JSON.parse(localStorage.getItem(key));if(validData(v))return v}catch{}return initialData()}
function validData(v){return !!v&&v.schema===1&&Array.isArray(v.events)&&v.events.length<=100&&v.events.every(e=>typeof e.id==='string'&&typeof e.title==='string'&&Array.isArray(e.tournaments)&&e.tournaments.length>0&&e.tournaments.length<=20&&e.tournaments.every(t=>t&&typeof t.id==='string'&&E.SPORTS[t.config?.sport]&&E.FORMULAS[t.config?.formula]&&Array.isArray(t.teams)&&Array.isArray(t.courts)&&Array.isArray(t.rotations)&&t.rotations.length>0&&t.rotations.every(r=>Array.isArray(r.matches)&&r.matches.every(m=>Array.isArray(m.a)&&Array.isArray(m.b)&&Number.isFinite(m.scoreA)&&Number.isFinite(m.scoreB)))&&t.roundIndex>=0&&t.roundIndex<t.rotations.length))}
let data=load(),view='home',tab='courts',draft=null,draftPreview=null,findId=null,findQuery='',rankGeneral=false,role=sessionStorage.getItem('eps-role')??'teacher',refCourtId=sessionStorage.getItem('eps-ref-court'),authorized=new Set(JSON.parse(sessionStorage.getItem('eps-authorized')??'[]')),tv=false,zoom=Number(sessionStorage.getItem('eps-zoom')??1),installEvent=null,audioContext=null,toastTimer=null,dbPromise=null,storageWarning=false,dragMember=null,lastAudioEnd=0;
function normalizeEvent(e){if(e.audio?.version!==2)e.audio={...e.audio,version:2,sound:e.audio?.sound==='custom'?'custom':'voice',enabled:e.audio?.enabled??true,volume:e.audio?.volume??.8,start:true,alert30:false,alert60:false};for(const t of e.tournaments){t.config.referees??=false;for(const x of t.teams)if(P.isIndividual(t.config.sport)&&/^Équipe \d+$/.test(x.name))x.name=x.name.replace('Équipe',t.config.format==='double'?'Duo':'Joueur');P.assignReferees(t)}return e}
data.events.forEach(normalizeEvent);
function rosterTerm(c,plural=false){if(!P.isIndividual(c.sport))return plural?'équipes':'équipe';return c.formula!=='americano'&&(c.playersPerSide===2||c.format==='double')?plural?'duos':'duo':plural?'joueurs':'joueur'}
const capital=s=>s[0].toUpperCase()+s.slice(1);
function validateNames(){if(!draft.teams.every(x=>x.name.trim()))throw Error('Saisissez les noms.');if(new Set(draft.teams.map(x=>x.name.trim().toLocaleLowerCase('fr-FR'))).size!==draft.teams.length)throw Error('Les noms doivent être différents.')}
function validateTiming(){const c=draftCfg();if(c.endMode!=='time')return;const plan=draftTiming();if(!plan.feasible||plan.setup+plan.rotations*c.duration+plan.transitionTotal>plan.budget)throw Error('La séance dépasse le temps du cours. Choisissez une durée plus courte, réduisez les rotations ou ajoutez des terrains.')}
let nextCache=new Map();
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('eps-tournois'):null;
const event=()=>data.events.find(e=>e.id===data.activeId);
const tourney=()=>event()?.tournaments.find(t=>t.id===event().selectedId)??event()?.tournaments[0];
const teacher=()=>!tv&&role==='teacher'&&(!event()?.pinHash||authorized.has(event().id));
const canScore=m=>!tv&&(teacher()||role==='referee'&&m.courtId===refCourtId||role==='student'&&event()?.studentScores);
const modes={teacher:'Enseignant',student:'Élève',referee:'Arbitre'};
function db(){if(!('indexedDB'in globalThis))return Promise.reject(Error('IndexedDB indisponible'));return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('eps-tournoi-offline',1);r.onupgradeneeded=()=>r.result.createObjectStore('snapshots');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbWrite(snapshot){const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('snapshots','readwrite');tx.objectStore('snapshots').put(snapshot,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function restoreDB(){try{const d=await db(),r=d.transaction('snapshots').objectStore('snapshots').get('current');r.onsuccess=()=>{if(validData(r.result)&&r.result.updatedAt>data.updatedAt){data=r.result;data.events.forEach(normalizeEvent);render();toast('Votre sauvegarde a été retrouvée.')}}}catch{}}
function save(){data.updatedAt=Date.now();data.revision=(data.revision??0)+1;const snapshot=JSON.stringify(data);let ok=false;try{const previous=localStorage.getItem(KEY);if(previous)localStorage.setItem(BACKUP,previous);localStorage.setItem(KEY,snapshot);ok=true}catch{try{localStorage.removeItem(BACKUP);localStorage.setItem(KEY,snapshot);ok=true}catch{}}dbWrite(structuredClone(data)).catch(()=>{if(!ok)toast('Sauvegarde impossible : exportez une copie JSON tout de suite.',true)});if(!ok&&!storageWarning){storageWarning=true;toast('Le stockage rapide est plein. Pensez à exporter une sauvegarde JSON.',true)}channel?.postMessage({type:'snapshot',data});}
function sync(v){if(validData(v)&&v.updatedAt>=data.updatedAt){data=v;data.events.forEach(normalizeEvent);render()}}
channel&&(channel.onmessage=e=>{if(e.data?.type==='snapshot')sync(e.data.data)});addEventListener('storage',e=>{if(e.key===KEY&&e.newValue)try{sync(JSON.parse(e.newValue))}catch{}});
function toast(message,persistent=false){clearTimeout(toastTimer);toastNode.textContent=message;toastNode.classList.add('show');if(!persistent)toastTimer=setTimeout(()=>toastNode.classList.remove('show'),4200)}
function dialog(title,content,footer=''){modal.innerHTML=`<div class="modal-header"><h2>${esc(title)}</h2>${btn(icon('close'),'close','icon-only','aria-label="Fermer"')}</div><div class="modal-content">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal()}
function footer(){return `<footer class="footer"><span>TOURNOI EPS</span><span>${data.updatedAt?'Sauvegardé · '+new Date(data.updatedAt).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}):'Vos tournois restent sur cet appareil'}</span></footer>`}
function brand(){return btn('<span class="brand-mark">T<span>↗</span></span><span>TOURNOI<small>EPS · LE JEU D’ABORD</small></span>','home','brand','aria-label="Accueil"')}
function topbar(){return `<header class="topbar">${brand()}<div class="top-actions">${view==='tournament'?`<span class="role-pill">${modes[role]??'Enseignant'}</span>${btn(icon('fullscreen'),'fullscreen','icon-only','aria-label="Plein écran"')}${teacher()?btn(icon('download'),'exports','icon-only','aria-label="Exporter"')+btn(icon('settings'),'settings','icon-only','aria-label="Réglages"') :''}${btn(icon('person'),'roles','icon-only','aria-label="Changer de rôle"')}`:btn(icon('upload')+' Mes sauvegardes','restore','small')}</div></header>`}
function home(){return `${topbar()}<section class="activity-home"><div class="home-heading"><span class="sticker">À VOS MARQUES !</span><h1>On joue <em>à quoi ?</em></h1><p>Choisissez une activité. Les terrains vous attendent.</p></div>${activityCards()}<section class="saved-events"><div class="flex between"><h2>Reprendre un tournoi</h2>${installEvent?btn('Installer','install','small'):''}</div><div class="saved-list">${data.events.length?data.events.slice().reverse().map(e=>{const t=e.tournaments[0];return btn(`<span class="saved-icon">${icon(E.SPORTS[t.config.sport].icon)}</span><span><strong>${esc(e.title)}</strong><small>${E.SPORTS[t.config.sport].name} · ${t.courts.length} terrains · ${e.tournaments.every(t=>t.completed)?'Terminé':'Reprendre'}</small></span><b>↗</b>`,'open-event','saved-event',`data-id="${e.id}"`)}).join(''):'<p class="muted">Vos tournois apparaîtront ici.</p>'}</div></section></section>${footer()}`}
function newDraft(s='basket'){draft={step:1,title:'Tournoi '+E.SPORTS[s].name,selected:[s],multi:false,editingSport:s,configs:{[s]:defaults(s)},count:6,teams:E.makeTeams(6),studentCount:28,mode:null,proposal:null,participants:[],assignment:'balanced',pin:'',studentScores:false,teamPage:0,formulaPage:0};if(P.isIndividual(s))draft.teams.forEach((x,i)=>x.name='Joueur '+(i+1));draftPreview=null;view='wizard';render()}
function defaults(s){const individual=P.isIndividual(s);return {sport:s,format:individual?'single':'custom',playersPerSide:individual?1:s==='volley'?3:4,courtCount:3,formula:'rr',endMode:'time',duration:300,target:s==='football'||s==='futsal'||s==='rugby'?3:s==='handball'?5:s==='volley'?15:11,sync:'common',stopPolicy:'individual',tie:'draw',overtime:60,breakSeconds:45,poolCount:2,qualifiers:2,roundCount:5,availableMinutes:90,setupMinutes:10,referees:false,winPoints:3,drawPoints:1,lossPoints:0,customText:''}}
