function resizeTeams(n){n=P.integer(n,2,64);draft.count=n;draft.teams=Array.from({length:n},(_,i)=>draft.teams[i]??{...E.makeTeams(1)[0],name:capital(rosterTerm(draftCfg()))+' '+(i+1),color:E.COLORS[i%E.COLORS.length]});draft.teamPage=Math.min(draft.teamPage??0,Math.floor((n-1)/8));draftPreview=null}
function assignDraft(){const c=draftCfg();if(!draft.participants.length)return;let teams;if(draft.assignment==='existing'&&draft.participants.some(p=>p.team)){const names=[...new Set(draft.participants.map(p=>p.team).filter(Boolean))];teams=names.map((name,i)=>({id:E.uid(),name,color:draft.participants.find(p=>p.team===name&&p.color)?.color??E.COLORS[i%E.COLORS.length],members:draft.participants.filter(p=>p.team===name),level:0,active:true}));draft.participants.filter(p=>!p.team).forEach((p,i)=>teams[i%teams.length].members.push(p))}else{teams=E.balancedTeams(draft.participants,draft.count,draft.assignment);if(P.isIndividual(c.sport))teams.forEach((x,i)=>x.name=c.playersPerSide===1&&x.members.length===1&&!x.members[0].placeholder?[x.members[0].first,x.members[0].last].filter(Boolean).join(' '):capital(rosterTerm(c))+' '+(i+1))}if(teams.length>64)throw Error('Maximum : 64 groupes de jeu.');const old=draft.teams;teams.forEach((x,i)=>{const prev=old[i];if(prev&& !/^(Équipe|Joueur|Duo) \d+$/.test(prev.name)){x.name=prev.name;x.color=prev.color;x.logo=prev.logo}});draft.teams=teams;draft.count=teams.length;draftPreview=null}
